// examples/base-2d: AF's 2D base project, a character in a room.
//
// Shows: the smallest complete game on AF. A pixel-art character runs and jumps through one single-screen room
// to an ember (Wick, a hooded lantern-bearer in mossy ruins at night, Endesga 64, lit by pixel lights),
// through splash → menu → room → pause → end. It completes the Ruken handshake and renders nothing before the
// host says ready; opened directly, it runs standalone.
// Controls: arrows or A/D to move, Space, Z, W or Up to jump, Escape or P to pause; on-screen buttons on touch.
// Base: this is the 2D base. Demos build on it through `@af-examples/base-2d`.
// Packages: @mcthaydt/automata-sim, @ruken/sdk, effect, pixi.js, @fontsource/pixelify-sans (OFL font);
// @mcthaydt/automata-ship for packaging.
import './src/no-eval.ts'
import '@fontsource/pixelify-sans/latin-400.css'
import '@fontsource/pixelify-sans/latin-700.css'
import { bootPage } from './src/boot-page.ts'
import { startGame } from './src/game.ts'

const root = document.querySelector<HTMLElement>('#game')
if (root === null) throw new Error('index.html has no #game element')

void bootPage({
  root,
  html: document.documentElement,
  start: startGame(root),
  log: (message, error) => console.error(message, error),
})

// What ship writes into this build's ruken.toml (ship spec §3.2). Field names and values are Ruken's own.
import { defineShipConfig } from '@mcthaydt/automata-ship'
import packageJson from './package.json' with { type: 'json' }

export default defineShipConfig({
  game: {
    id: 'base-2d',
    title: 'AF Base 2D',
    // From package.json, so the manifest can never disagree with the package (FloorFifty ruken-pack.ts).
    version: packageJson.version,
    entry: 'index.html',
    // The vendored SDK's version (vendor/ruken/README.md); Ruken reads it as a caret range.
    sdk: '^0.0.0',
  },
  runtime: {
    // Pixi's `webgl` preference creates a WebGL2 context: AF's default renderer (master spec §12).
    renderer: 'webgl2',
    orientation: 'any',
    inputs: ['touch', 'keyboard'],
    pause_behavior: 'pause',
  },
  network: { connect: [] },
  content: { languages: ['en'], rating: 'everyone', descriptors: [] },
})

import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { ENDESGA_64, endesga } from './palette.ts'
import { ALL_SPRITES } from './sprites.ts'

// The palette gate the pipelines will run in M3, in miniature: every color the base draws is an Endesga 64
// color, checked against the palette file exactly as the Owner supplied it (docs/art/palettes/endesga-64.txt).
const paletteFile = readFileSync(
  new URL('../../../../docs/art/palettes/endesga-64.txt', import.meta.url),
  'utf8',
)
const fromFile = paletteFile
  .split(/\r?\n/)
  .filter((line) => line !== '' && !line.startsWith(';'))
  .map((line) => `#${line.slice(2).toLowerCase()}`) // AARRGGBB → #rrggbb

describe('the palette', () => {
  it('is Endesga 64, in the file’s order', () => {
    expect(fromFile).toHaveLength(64)
    expect(ENDESGA_64).toEqual(fromFile)
  })

  it('looks colors up by their index in the file', () => {
    expect(endesga(0)).toBe('#ff0040')
    expect(endesga(63)).toBe('#571c27')
    expect(() => endesga(64)).toThrow('Endesga 64 has no color 64')
  })
})

describe('the sprites', () => {
  it.each(Object.entries(ALL_SPRITES))('%s is a rectangle of known palette keys', (_name, sprite) => {
    expect(sprite.rows).toHaveLength(sprite.height)
    for (const row of sprite.rows) {
      expect(row).toHaveLength(sprite.width)
      for (const key of row) if (key !== '.') expect(sprite.palette).toHaveProperty(key)
    }
  })

  it.each(Object.entries(ALL_SPRITES))('%s uses only Endesga 64 colors', (_name, sprite) => {
    for (const color of Object.values(sprite.palette)) expect(fromFile).toContain(color)
  })
})

// Sets up the base's sim: the room as content, the plugin, and the character at the room's start. Demos and
// games start from here (`@af-examples/base-2d`), then add their own plugins.
import { type Command, createSim, type PluginDef, type Sim } from '@mcthaydt/automata-sim'
import { parseRoom, ROOM, type RoomSource } from './content/room.ts'
import { base2dPlugin, type MoveInput, Player, PlayerControl } from './sim/index.ts'
import { HITBOX_H, SUB, TICK_HZ } from './sim/tuning.ts'

export interface BaseSimOptions {
  readonly seed?: number
  readonly room?: RoomSource
  /** Extra plugins a demo adds on top of the base. */
  readonly plugins?: readonly PluginDef[]
}

export async function createBaseSim(options: BaseSimOptions = {}): Promise<Sim> {
  const room = parseRoom(options.room ?? ROOM)
  const sim = await createSim({
    seed: options.seed ?? 1,
    tickHz: TICK_HZ,
    content: { room },
    plugins: [base2dPlugin, ...(options.plugins ?? [])],
  })
  // Standing on the tile below P: feet on that tile's top edge.
  const x = room.start.tx * room.tileSize * SUB
  const y = ((room.start.ty + 1) * room.tileSize - HITBOX_H) * SUB
  sim.spawn([[Player, { x, y, facing: 1 }], PlayerControl])
  return sim
}

/** This tick's `move` command from player slot 0. One per tick, so the tick doubles as the sequence number. */
export function moveCommand(sim: Sim, input: MoveInput): Command {
  return { tick: sim.tick, source: 0, seq: sim.tick, type: 'move', payload: input }
}

/** The character's current state. */
export function readPlayer(sim: Sim): Readonly<{
  x: number
  y: number
  vx: number
  vy: number
  facing: number
  grounded: boolean
}> {
  const [player] = sim.query(Player)
  if (player === undefined) throw new Error('base-2d: the sim has no player')
  return player.get(Player)
}

import { Cause, Effect, Exit, FiberId } from 'effect'
import { describe, expect, it } from 'vitest'
import { BaseBootFailed } from './boot.ts'
import {
  bootFailureMessage,
  CONNECT_FAILED,
  DEVICE_FAILED,
  RendererFailed,
  SimFailed,
} from './boot-failure.ts'

// The page's error screen picks its message from how startGame failed. Run through Effect.runPromiseExit, as
// main.ts does: Effect.runPromise would hand back a FiberFailure wrapper with no `_tag` of its own.
async function messageFor(program: Effect.Effect<void, unknown>): Promise<string> {
  const exit = await Effect.runPromiseExit(program)
  if (Exit.isSuccess(exit)) throw new Error('expected the program to fail')
  return bootFailureMessage(exit.cause)
}

describe('bootFailureMessage', () => {
  it('blames the connection only when the Ruken handshake or ready failed', async () => {
    expect(await messageFor(Effect.fail(new BaseBootFailed({ step: 'init', cause: 'no host' })))).toBe(
      CONNECT_FAILED,
    )
    expect(await messageFor(Effect.fail(new BaseBootFailed({ step: 'ready', cause: 'timeout' })))).toBe(
      CONNECT_FAILED,
    )
  })

  it('says the device cannot run the game when the renderer or the sim (Rapier) could not load', async () => {
    expect(await messageFor(Effect.fail(new RendererFailed({ cause: 'no WebGL2' })))).toBe(DEVICE_FAILED)
    expect(await messageFor(Effect.fail(new SimFailed({ cause: 'wasm blocked' })))).toBe(DEVICE_FAILED)
  })

  it('says the device cannot run the game for anything unexpected (a defect or an interruption)', async () => {
    expect(await messageFor(Effect.die(new Error('bug')))).toBe(DEVICE_FAILED)
    expect(bootFailureMessage(Cause.interrupt(FiberId.none))).toBe(DEVICE_FAILED)
  })
})

import { Cause, Data, Option } from 'effect'
import { BaseBootFailed } from './boot.ts'

// What the page says when the game cannot start (main.ts). Only a failed Ruken handshake or ready is a
// connection problem; everything else (no canvas context, a sim that can't be made, a bug) means this
// device can't run the game, and a "check your connection" message would send the player looking in the wrong
// place.

/** The renderer could not start (Pixi found no canvas context it can draw with). */
export class RendererFailed extends Data.TaggedError('RendererFailed')<{ readonly cause: unknown }> {}

/** The first sim could not be made (its world could not be created, or a module it loads failed to load). */
export class SimFailed extends Data.TaggedError('SimFailed')<{ readonly cause: unknown }> {}

export const CONNECT_FAILED = "Couldn't connect to Ruken."
export const DEVICE_FAILED = "This device can't run the game."

/**
 * Picks the message from how startGame ended. It takes the Exit's Cause rather than the error Effect.runPromise
 * rejects with: that is a FiberFailure wrapper, whose own `_tag` is never the failure's tag.
 */
export function bootFailureMessage(cause: Cause.Cause<unknown>): string {
  const failure = Cause.failureOption(cause)
  if (Option.isSome(failure) && failure.value instanceof BaseBootFailed) return CONNECT_FAILED
  return DEVICE_FAILED
}

import { Effect } from 'effect'
import { describe, expect, it, vi } from 'vitest'
import { BaseBootFailed } from './boot.ts'
import { CONNECT_FAILED, DEVICE_FAILED, RendererFailed, SimFailed } from './boot-failure.ts'
import { bootPage } from './boot-page.ts'

// main.ts hands startGame to bootPage; this is what the player sees for each way it can end.
async function pageAfter(start: Effect.Effect<void, unknown>) {
  const root = { textContent: '' }
  const html = { dataset: {} as Record<string, string> }
  const log = vi.fn()
  await bootPage({ root, html, start, log })
  return { text: root.textContent, state: html.dataset.state, log }
}

describe('bootPage', () => {
  it('marks the page ready when the game starts', async () => {
    const page = await pageAfter(Effect.void)
    expect(page.state).toBe('ready')
    expect(page.text).toBe('')
    expect(page.log).not.toHaveBeenCalled()
  })

  it('shows the connection message only when the Ruken handshake fails', async () => {
    const page = await pageAfter(Effect.fail(new BaseBootFailed({ step: 'init', cause: 'no host' })))
    expect(page).toMatchObject({ text: CONNECT_FAILED, state: 'failed' })
  })

  it('shows the device message when the renderer or the sim cannot start, or on a defect', async () => {
    for (const start of [
      Effect.fail(new RendererFailed({ cause: 'no canvas context' })),
      Effect.fail(new SimFailed({ cause: 'wasm blocked' })),
      Effect.die(new Error('bug')),
    ]) {
      expect(await pageAfter(start)).toMatchObject({ text: DEVICE_FAILED, state: 'failed' })
    }
  })

  it('logs the underlying error, not only the failure tag', async () => {
    const underlying = new Error('CompileError: wasm blocked')
    const page = await pageAfter(Effect.fail(new SimFailed({ cause: underlying })))
    expect(page.log).toHaveBeenCalledWith(expect.any(String), underlying)
  })
})

import { Cause, Effect, Exit } from 'effect'
import { bootFailureMessage } from './boot-failure.ts'

export interface BootPageParts {
  /** The game's root element; on a failure its text becomes the message. */
  readonly root: { textContent: string | null }
  /** The <html> element; `data-state` becomes `ready` or `failed` (the browser journeys wait on it). */
  readonly html: { dataset: Record<string, string | undefined> }
  /** startGame(root), or any boot program in tests. */
  readonly start: Effect.Effect<void, unknown>
  readonly log: (message: string, error: unknown) => void
}

/**
 * Runs the boot and shows how it ended. runPromiseExit, not runPromise: the Exit keeps the failure itself,
 * while runPromise rejects with a FiberFailure wrapper whose `_tag` is never the failure's.
 */
export async function bootPage(parts: BootPageParts): Promise<void> {
  const exit = await Effect.runPromiseExit(parts.start)
  if (Exit.isSuccess(exit)) {
    parts.html.dataset.state = 'ready'
    return
  }
  parts.root.textContent = bootFailureMessage(exit.cause)
  parts.html.dataset.state = 'failed'
  // The underlying error (Ruken's, the loader's), not just the tag: Cause.pretty prints only "SimFailed: An
  // error has occurred".
  parts.log('base-2d: the game could not start', underlyingError(exit.cause))
}

function underlyingError(cause: Cause.Cause<unknown>): unknown {
  const error = Cause.squash(cause)
  return typeof error === 'object' && error !== null && 'cause' in error ? error.cause : error
}

import { createFakeHost, settle } from '@ruken/sdk-host/testing'
import { Effect } from 'effect'
import { describe, expect, it } from 'vitest'
import { connect, GAME_ID } from './boot.ts'

// The base's connection to Ruken under Ruken's own fake host (`@ruken/sdk-host/testing`, in-memory ports): the
// real SDK against the real host bridge, as in examples/placeholder.

const clock = {
  epochMs: () => Date.parse('2026-10-11T12:00:00Z'),
  setTimeout: (fn: () => void, ms: number) => setTimeout(fn, ms),
  clearTimeout: (handle: unknown) => clearTimeout(handle as ReturnType<typeof setTimeout>),
}

function fakeHost(autoReady: boolean) {
  const host = createFakeHost({
    gameOrigin: 'http://localhost:4400',
    gameId: GAME_ID,
    clock,
    autoReady,
    player: { id: 'p-1', displayName: 'Ada' },
  })
  if (host.gameEnv === null) throw new Error('in-memory mode exposes gameEnv')
  return { host, env: host.gameEnv }
}

describe('connecting to Ruken', () => {
  it('completes the handshake and resolves once the host is ready', async () => {
    const { host, env } = fakeHost(true)
    const session = await Effect.runPromise(connect({ env, onMenuRequest: () => true }))
    expect(session.hosted).toBe(true)
    expect(session.player.displayName).toBe('Ada')
    expect(host.messages.map((entry) => entry.msg.type).slice(0, 3)).toEqual([
      'hello',
      'welcome',
      'session.ready',
    ])
    session.dispose()
    host.dispose()
  })

  it('does not resolve before the host says ready, and refuses the host menu until then', async () => {
    const { host, env } = fakeHost(false)
    let resolved = false
    let menuCalls = 0
    const connecting = Effect.runPromise(
      connect({
        env,
        onMenuRequest: () => {
          menuCalls++
          return true
        },
      }),
    ).then((session) => {
      resolved = true
      return session
    })
    await settle()
    await host.connected()
    expect(host.bridge.state).toBe('welcomed')
    expect(resolved).toBe(false)
    expect(await host.bridge.openGameMenu()).toBe(false)
    expect(menuCalls).toBe(0)

    await host.bridge.markReady()
    const session = await connecting
    expect(resolved).toBe(true)
    expect(await host.bridge.openGameMenu()).toBe(true)
    expect(menuCalls).toBe(1)
    session.dispose()
    host.dispose()
  })

  it('runs standalone when opened outside Ruken', async () => {
    const { host, env } = fakeHost(true)
    const session = await Effect.runPromise(
      connect({ env: { ...env, isTopLevel: true }, onMenuRequest: () => true }),
    )
    expect(session.hosted).toBe(false)
    session.dispose()
    host.dispose()
  })
})

import { Ruken, type RukenSession, type SdkEnv } from '@ruken/sdk'
import { Data, Effect } from 'effect'

// The connection to Ruken: the handshake, then the wait for ready. It calls the SDK directly, a stand-in from
// before the `Hosting` service (host lane, M1.4, PR #5) merged; moving onto `HostingLive` is the next step for
// this file. Opened outside Ruken, the SDK runs standalone and this resolves at once.

/** Must equal `[game] id` in ship.config.ts; Ruken checks it. */
export const GAME_ID = 'base-2d'

/** The handshake or the wait for ready failed (Ruken's error is kept as the cause). */
export class BaseBootFailed extends Data.TaggedError('BaseBootFailed')<{
  readonly step: 'init' | 'ready'
  readonly cause: unknown
}> {}

export interface ConnectOptions {
  /** The host's "Open game menu". Return false when the menu cannot open right now. */
  readonly onMenuRequest: () => boolean
  /** The fake host's environment in tests; the real window when omitted. */
  readonly env?: SdkEnv | undefined
}

export function connect(options: ConnectOptions): Effect.Effect<RukenSession, BaseBootFailed> {
  return Effect.gen(function* () {
    // Ruken does not refuse menu.open before session.ready (a known item sent to Ruken, docs/03), so the game
    // refuses it itself until the host says ready: there is no game to pause yet.
    let ready = false
    const session = yield* Effect.tryPromise({
      try: () =>
        Ruken.init(
          {
            gameId: GAME_ID,
            // 'menu' lets the host's "Open game menu" reach the game; the host grants it only with onMenuRequest set.
            wants: ['menu'],
            pauseBehavior: 'pause',
            onMenuRequest: () => ready && options.onMenuRequest(),
          },
          options.env,
        ),
      catch: (cause) => new BaseBootFailed({ step: 'init', cause }),
    })
    yield* Effect.tryPromise({
      try: () => session.ready,
      catch: (cause) => new BaseBootFailed({ step: 'ready', cause }),
    })
    ready = true
    return session
  })
}

import { describe, expect, it } from 'vitest'
import { isSolid, parseRoom, ROOM, type RoomSource } from './room.ts'

const tiny = (rows: string[]): RoomSource => ({ id: 'tiny', tileSize: 8, rows })

describe('the room', () => {
  it('is 40 by 24 tiles of 8 pixels with one start and one goal', () => {
    const room = parseRoom(ROOM)
    expect(room.width).toBe(40)
    expect(room.height).toBe(24)
    expect(room.tileSize).toBe(8)
    expect(isSolid(room, room.start.tx, room.start.ty)).toBe(false)
    expect(isSolid(room, room.goal.tx, room.goal.ty)).toBe(false)
    // The start stands on the floor: the tile below it is solid.
    expect(isSolid(room, room.start.tx, room.start.ty + 1)).toBe(true)
  })

  it('finds the start and the goal', () => {
    const room = parseRoom(tiny(['####', '#..#', '#PG#', '####']))
    expect(room.start).toEqual({ tx: 1, ty: 2 })
    expect(room.goal).toEqual({ tx: 2, ty: 2 })
  })

  it('treats everything outside the room as solid', () => {
    const room = parseRoom(tiny(['....', '.PG.', '....', '....']))
    expect(isSolid(room, -1, 0)).toBe(true)
    expect(isSolid(room, 4, 0)).toBe(true)
    expect(isSolid(room, 0, -1)).toBe(true)
    expect(isSolid(room, 0, 4)).toBe(true)
    expect(isSolid(room, 0, 0)).toBe(false)
  })

  it('rejects ragged rows, naming the row', () => {
    expect(() => parseRoom(tiny(['####', '#..#', '#PG', '####']))).toThrow(
      'row 2 is 3 tiles wide, expected 4',
    )
  })

  it('rejects unknown tiles, naming where they are', () => {
    expect(() => parseRoom(tiny(['####', '#..#', '#PGx', '####']))).toThrow(
      'unknown tile "x" at column 3, row 2',
    )
  })

  it('needs room above the start for the character, who is a tile and a half tall', () => {
    expect(() => parseRoom(tiny(['####', '#PG#', '####']))).toThrow(
      'the tile above P (column 1, row 0) must be empty',
    )
  })

  it('needs exactly one start and one goal', () => {
    expect(() => parseRoom(tiny(['####', '#..#', '#PP#', '#G.#']))).toThrow('needs exactly one P, found 2')
    expect(() => parseRoom(tiny(['####', '#..#', '#P.#', '####']))).toThrow('needs exactly one G, found 0')
  })
})

// The base's one room, as content. Stand-in until the content compiler lands (M1.3, PR #8): then this becomes a
// `content/rooms/*.toml` file compiled by `automata-content`. The sim receives it as `content`, so the room is
// frozen and hashed together with the sim state either way.
//
// Tiles: `#` solid, `.` empty, `P` where the character starts (standing on the tile below), `G` the ember (the goal).
// 40 × 24 tiles of 8 pixels is 320 × 192 pixels: a single screen, Bubble Bobble style. Platforms climb in steps
// of three tiles, about the height of a held jump, with two free rows under each so the character can walk under.

import type { RoomGrid, TilePosition } from '../sim/tiles.ts'

export { isSolid } from '../sim/tiles.ts'

export interface RoomSource {
  readonly id: string
  readonly tileSize: number
  readonly rows: readonly string[]
}

/** A checked room: its size in tiles, and where the start and the goal are. */
export interface Room extends RoomGrid {
  readonly id: string
}

export const ROOM: RoomSource = {
  id: 'room-1',
  tileSize: 8,
  rows: [
    '########################################',
    '#......................................#',
    '#......................................#',
    '#..............G.......................#',
    '#......................................#',
    '#...........#######....................#',
    '#......................................#',
    '#......................................#',
    '#....................########..........#',
    '#...######.............................#',
    '#......................................#',
    '#...............................######.#',
    '#......................................#',
    '#......................................#',
    '#..######..............########........#',
    '#......................................#',
    '#......................................#',
    '#............########..................#',
    '#......................................#',
    '#......................................#',
    '#..########............................#',
    '#.............................##.......#',
    '#.....P.......................##.......#',
    '########################################',
  ],
}

const TILES = new Set(['#', '.', 'P', 'G'])

/** Checks a room and finds its start and goal. Throws, naming the row and column, on anything malformed. */
export function parseRoom(source: RoomSource): Room {
  const width = source.rows[0]?.length ?? 0
  const starts: TilePosition[] = []
  const goals: TilePosition[] = []
  source.rows.forEach((row, ty) => {
    if (row.length !== width)
      throw new Error(`room ${source.id}: row ${ty} is ${row.length} tiles wide, expected ${width}`)
    for (let tx = 0; tx < row.length; tx++) {
      const tile = row.charAt(tx)
      if (!TILES.has(tile))
        throw new Error(`room ${source.id}: unknown tile "${tile}" at column ${tx}, row ${ty}`)
      if (tile === 'P') starts.push({ tx, ty })
      if (tile === 'G') goals.push({ tx, ty })
    }
  })
  const start = exactlyOne(source.id, 'P', starts)
  const goal = exactlyOne(source.id, 'G', goals)
  // The character is a tile and a half tall, so it stands in P's tile and half of the one above.
  if (source.rows[start.ty - 1]?.charAt(start.tx) !== '.')
    throw new Error(
      `room ${source.id}: the tile above P (column ${start.tx}, row ${start.ty - 1}) must be empty`,
    )
  return {
    id: source.id,
    tileSize: source.tileSize,
    width,
    height: source.rows.length,
    rows: source.rows,
    start,
    goal,
  }
}

function exactlyOne(roomId: string, tile: string, found: readonly TilePosition[]): TilePosition {
  const [first] = found
  if (found.length !== 1 || first === undefined)
    throw new Error(`room ${roomId}: needs exactly one ${tile}, found ${found.length}`)
  return first
}

import { describe, expect, it } from 'vitest'

// The entries demos import (examples/README.md), resolved by package name as a demo resolves them. The root
// and ./sim stay free of Pixi, so Node code (sims, goldens) that reads the room or the plugin never loads the
// renderer; the game and the renderer have their own entries.
// Each test imports a whole entry cold, which took 5.6 s on a loaded runner (past vitest's 5 s default), so the
// block gets the same 30 s allowance as ship's deploy tests.
describe('@af-examples/base-2d entries', { timeout: 30_000 }, () => {
  it('the root has the sim setup, the room, bootPage and the boot failures, but not the game', async () => {
    const root = await import('@af-examples/base-2d')
    expect(typeof root.createBaseSim).toBe('function')
    expect(typeof root.bootPage).toBe('function')
    expect(typeof root.SimFailed).toBe('function')
    expect('startGame' in root).toBe(false)
  })

  it('./game has startGame', async () => {
    const game = await import('@af-examples/base-2d/game')
    expect(typeof game.startGame).toBe('function')
  })

  it('./sim has the sim plugin and its definitions, for a demo’s own sim root', async () => {
    const sim = await import('@af-examples/base-2d/sim')
    expect(sim.base2dPlugin.name).toBe('base-2d')
    expect(sim.Player).toBeDefined()
  })
})

import { describe, expect, it } from 'vitest'
import { createFailure } from './failure.ts'

function parts() {
  const calls: string[] = []
  const root = { textContent: 'game' }
  const html = { dataset: { state: 'ready' } as Record<string, string> }
  const failure = createFailure({
    root,
    html,
    stopLoop: () => calls.push('loop.stop'),
    endRound: (outcome) => calls.push(`round.end:${outcome}`),
    cleanups: [() => calls.push('input.dispose'), () => calls.push('resize.off')],
    log: () => calls.push('log'),
  })
  return { calls, root, html, failure }
}

describe('a failed round', () => {
  it('ends the host round as failed, stops everything and says so', () => {
    const { calls, root, html, failure } = parts()
    expect(failure.failed()).toBe(false)
    failure.fail(new Error('Too many worlds'))
    expect(failure.failed()).toBe(true)
    expect(calls).toEqual(['log', 'loop.stop', 'round.end:fail', 'input.dispose', 'resize.off'])
    expect(root.textContent).toBe("This device can't run the game.")
    expect(html.dataset.state).toBe('failed')
  })

  it('is terminal: failing again does nothing more', () => {
    const { calls, failure } = parts()
    failure.fail(new Error('first'))
    const after = calls.length
    failure.fail(new Error('second'))
    expect(calls).toHaveLength(after)
  })
})

import type { RoundOutcome } from '@ruken/sdk'
import { DEVICE_FAILED } from './boot-failure.ts'

// What happens when a round's sim cannot be made (out of Koota worlds or memory): there is nothing to play on,
// so the game stops for good. It ends the round it told the host about, stops the loop, removes its input and
// window listeners so no key press can reach a disposed sim, and shows the same message and page state as a
// boot failure (main.ts). Terminal: after the first failure every later call does nothing.

export interface FailureParts {
  readonly root: { textContent: string | null }
  readonly html: { dataset: Record<string, string | undefined> }
  readonly stopLoop: () => void
  readonly endRound: (outcome: RoundOutcome) => void
  /** Removes listeners: input devices, resize, and anything else that could still call into the game. */
  readonly cleanups: ReadonlyArray<() => void>
  readonly log: (error: unknown) => void
}

export interface Failure {
  failed(): boolean
  fail(error: unknown): void
}

export function createFailure(parts: FailureParts): Failure {
  let failed = false
  return {
    failed: () => failed,
    fail(error) {
      if (failed) return
      failed = true
      parts.log(error)
      parts.stopLoop()
      parts.endRound('fail')
      for (const cleanup of parts.cleanups) cleanup()
      parts.root.textContent = DEVICE_FAILED
      parts.html.dataset.state = 'failed'
    },
  }
}

