      expect([tx, ty]).not.toEqual([shipped.goal.tx, shipped.goal.ty])
    }
  })
})

import type { Room } from '../content/room.ts'
import { isSolid } from '../content/room.ts'

// A small autotiler: which stone goes where, which edges and moss caps lie over it, and where the grass,
// glowing mushrooms and vines grow. Pure and deterministic (a hash of the tile's position, no randomness),
// so every run and every screenshot shows the same room. Presentation only: the sim never reads it.

export type Overlay = 'mossTop' | 'edgeLeft' | 'edgeRight' | 'edgeBottom'

export interface TileAt {
  readonly tx: number
  readonly ty: number
}

export interface TilePlan {
  /** Every solid tile, with which of the three stone variants it shows. */
  readonly stone: ReadonlyArray<TileAt & { readonly variant: 0 | 1 | 2 }>
  readonly overlays: ReadonlyArray<TileAt & { readonly piece: Overlay }>
  /** Open tiles standing on a mossy top. */
  readonly grass: readonly TileAt[]
  readonly mushrooms: readonly TileAt[]
  /** Open tiles a vine hangs through; `end` marks its last piece. */
  readonly vines: ReadonlyArray<TileAt & { readonly end: boolean }>
}

/** A small integer hash of a tile position, spread enough that neighbours differ. */
function hash(tx: number, ty: number): number {
  return (Math.imul(tx, 73856093) ^ Math.imul(ty, 19349663)) >>> 0
}

export function planTiles(room: Room): TilePlan {
  const stone: Array<TileAt & { variant: 0 | 1 | 2 }> = []
  const overlays: Array<TileAt & { piece: Overlay }> = []
  const grass: TileAt[] = []
  const mushrooms: TileAt[] = []
  const vines: Array<TileAt & { end: boolean }> = []
  const reserved = (tx: number, ty: number) =>
    (tx === room.start.tx && ty === room.start.ty) || (tx === room.goal.tx && ty === room.goal.ty)

  for (let ty = 0; ty < room.height; ty++)
    for (let tx = 0; tx < room.width; tx++) {
      if (!isSolid(room, tx, ty)) continue
      const h = hash(tx, ty)
      stone.push({ tx, ty, variant: (h % 3) as 0 | 1 | 2 })
      if (!isSolid(room, tx, ty - 1)) {
        overlays.push({ tx, ty, piece: 'mossTop' })
        // Something grows on about half the mossy tops: mostly grass, now and then a mushroom.
        if (!reserved(tx, ty - 1)) {
          if (h % 11 === 0) mushrooms.push({ tx, ty: ty - 1 })
          else if (h % 2 === 0) grass.push({ tx, ty: ty - 1 })
        }
      }
      if (!isSolid(room, tx - 1, ty)) overlays.push({ tx, ty, piece: 'edgeLeft' })
      if (!isSolid(room, tx + 1, ty)) overlays.push({ tx, ty, piece: 'edgeRight' })
      if (!isSolid(room, tx, ty + 1)) {
        overlays.push({ tx, ty, piece: 'edgeBottom' })
        // About one underside in five has a vine, one or two tiles long, stopping above anything solid.
        if (h % 5 === 0) {
          const length = 1 + ((h >> 3) % 2)
          for (let i = 1; i <= length; i++) {
            const below = ty + i
            if (isSolid(room, tx, below) || reserved(tx, below)) break
            const last = i === length || isSolid(room, tx, below + 1)
            vines.push({ tx, ty: below, end: last })
            if (last) break
          }
        }
      }
    }
  return { stone, overlays, grass, mushrooms, vines }
}

import { describe, expect, it } from 'vitest'
import { createRounds } from './rounds.ts'

interface FakeSim {
  readonly name: string
  disposed: number
  dispose(): void
}
const fake = (name: string): FakeSim => ({
  name,
  disposed: 0,
  dispose() {
    this.disposed++
  },
})

/** A sim factory whose results arrive only when the test settles them, one creation at a time. */
function slowFactory() {
  const pending: Array<{ resolve: (sim: FakeSim) => void; reject: (error: Error) => void }> = []
  let made = 0
  return {
    create: () =>
      new Promise<FakeSim>((resolve, reject) => {
        pending.push({ resolve, reject })
      }),
    inFlight: () => pending.length,
    resolveNext: () => {
      const sim = fake(`sim-${++made}`)
      pending.shift()?.resolve(sim)
      return sim
    },
    rejectNext: (error: Error) => pending.shift()?.reject(error),
  }
}

const flush = () => new Promise((resolve) => setTimeout(resolve, 0))

function setup() {
  const first = fake('first')
  const factory = slowFactory()
  const ready: string[] = []
  const failures: unknown[] = []
  const rounds = createRounds(first, factory.create, {
    onReady: (sim) => ready.push(sim.name),
    onFailed: (error) => failures.push(error),
  })
  return { first, factory, ready, failures, rounds }
}

describe('rounds', () => {
  it('swaps in a fresh sim and disposes the old one once', async () => {
    const { first, factory, ready, rounds } = setup()
    rounds.start()
    expect(rounds.starting()).toBe(true)
    const fresh = factory.resolveNext()
    await flush()
    expect(rounds.current()).toBe(fresh)
    expect(rounds.starting()).toBe(false)
    expect(first.disposed).toBe(1)
    expect(ready).toEqual(['sim-1'])
  })

  it('makes one sim at a time, and only the newest start is kept', async () => {
    const { first, factory, ready, rounds } = setup()
    rounds.start()
    rounds.start()
    rounds.start()
    expect(factory.inFlight()).toBe(1)
    const stale = factory.resolveNext()
    await flush()
    expect(stale.disposed).toBe(1)
    expect(rounds.starting()).toBe(true)
    expect(factory.inFlight()).toBe(1)
    const newest = factory.resolveNext()
    await flush()
    expect(rounds.current()).toBe(newest)
    expect(first.disposed).toBe(1)
    expect(ready).toEqual(['sim-2'])
  })

  it('never has more than two sims alive, however fast rounds start (Koota allows 16 worlds)', async () => {
    const { factory, rounds } = setup()
    for (let i = 0; i < 20; i++) rounds.start()
    expect(factory.inFlight()).toBe(1)
    factory.resolveNext()
    await flush()
    expect(factory.inFlight()).toBe(1)
  })

  it('reports a failed sim, stops starting and leaves no unhandled rejection', async () => {
    const { factory, failures, ready, rounds } = setup()
    rounds.start()
    const error = new Error('Too many worlds')
    factory.rejectNext(error)
    await flush()
    expect(failures).toEqual([error])
    expect(ready).toEqual([])
    expect(rounds.starting()).toBe(false)
  })
})

// Each round plays on a fresh sim, and making one is asynchronous. Play, Quit and Play again faster than a
// sim is made must not start overlapping creations: each holds a Koota world (Koota allows 16), the slower
// could overwrite the faster, and the loop could step a disposed sim. So one sim is made at a time. A start
// that arrives while one is being made only marks that another is wanted; when the sim in progress arrives it
// is disposed and the newest start's sim is made instead. At most two sims are alive at once.

export interface Rounds<S> {
  /** The sim to step. While a round is starting it is the old, disposed sim: don't step it. */
  current(): S
  /** True from `start()` until the newest round's sim has arrived (or failed). */
  starting(): boolean
  /** Disposes the current sim (once) and makes a fresh one. */
  start(): void
}

export interface RoundCallbacks<S> {
  /** The newest round's sim has arrived and is current. */
  readonly onReady: (sim: S) => void
  /** Making a sim failed; no round is starting any more. */
  readonly onFailed: (error: unknown) => void
}

export function createRounds<S extends { dispose(): void }>(
  first: S,
  create: () => Promise<S>,
  callbacks: RoundCallbacks<S>,
): Rounds<S> {
  let sim = first
  let starting = false
  let making = false
  let wantAnother = false

  const make = () => {
    making = true
    create().then(
      (fresh) => {
        making = false
        if (wantAnother) {
          // A newer start came in while this sim was being made: this one is stale.
          wantAnother = false
          fresh.dispose()
          make()
          return
        }
        sim = fresh
        starting = false
        callbacks.onReady(fresh)
      },
      (error: unknown) => {
        making = false
        wantAnother = false
        starting = false
        callbacks.onFailed(error)
      },
    )
  }

  return {
    current: () => sim,
    starting: () => starting,
    start() {
      // While a round is starting the old sim is already disposed; dispose it only on the first start.
      if (!starting) sim.dispose()
      starting = true
      if (making) wantAnother = true
      else make()
    },
  }
}

import type { Screen } from '../flow.ts'

// The base's screens as plain DOM over the canvas. Stand-in for the `ui` primitives (M1.6, PR #7): 44 px
// controls, 48 px primary actions, Endesga 64 colors, focus moved to each screen's primary action. Layout
// follows the container (style.css), not the viewport.

export interface ScreenHandlers {
  readonly onContinue: () => void
  readonly onPlay: () => void
  readonly onPause: () => void
  readonly onResume: () => void
  readonly onQuit: () => void
}

export interface Screens {
  /** The element the renderer puts its canvas in. */
  readonly stage: HTMLElement
  readonly touchButtons: readonly HTMLElement[]
  show(screen: Screen, details?: { seconds?: number }): void
}

export function createScreens(root: HTMLElement, handlers: ScreenHandlers): Screens {
  root.innerHTML = `
    <div class="stage-box"></div>
    <section class="panel" data-for="splash" aria-label="Splash">
      <p class="mark">AutomataFramework</p>
      <p class="hint blink">Press any key or tap</p>
    </section>
    <section class="panel" data-for="menu" aria-labelledby="menu-title">
      <h1 id="menu-title" class="title">Emberwick</h1>
      <p class="hint">Carry your lantern up to the ember.</p>
      <div class="actions"><button type="button" class="primary" data-action="play">Play</button></div>
      <p class="keys"><kbd>←</kbd><kbd>→</kbd> move <kbd>Space</kbd> jump <kbd>Esc</kbd> pause</p>
    </section>
    <section class="panel" data-for="paused" aria-labelledby="paused-title">
      <h2 id="paused-title">Paused</h2>
      <div class="actions">
        <button type="button" class="primary" data-action="resume">Resume</button>
        <button type="button" data-action="quit">Quit</button>
      </div>
    </section>
    <section class="panel" data-for="end" aria-labelledby="end-title">
      <h2 id="end-title">The ember is yours</h2>
      <p class="time" data-slot="time"></p>
      <div class="actions">
        <button type="button" class="primary" data-action="play">Play again</button>
        <button type="button" data-action="quit">Menu</button>
      </div>
    </section>
    <div class="hud" data-for="room">
      <button type="button" class="pause" data-action="pause" aria-label="Pause">II</button>
    </div>
    <div class="touch" data-for="room" aria-hidden="true">
      <button type="button" tabindex="-1" data-hold="left">◀</button>
      <button type="button" tabindex="-1" data-hold="right">▶</button>
      <button type="button" tabindex="-1" data-hold="jump" class="jump">▲</button>
    </div>`

  const actions: Record<string, () => void> = {
    play: handlers.onPlay,
    pause: handlers.onPause,
    resume: handlers.onResume,
    quit: handlers.onQuit,
  }
  root.addEventListener('click', (event) => {
    const button = (event.target as HTMLElement).closest<HTMLElement>('[data-action]')
    const action = button?.dataset.action
    if (action !== undefined) actions[action]?.()
  })
  root.querySelector('[data-for="splash"]')?.addEventListener('click', handlers.onContinue)

  const stage = root.querySelector<HTMLElement>('.stage-box')
  if (stage === null) throw new Error('screens: no stage')
  const time = root.querySelector<HTMLElement>('[data-slot="time"]')

  return {
    stage,
    touchButtons: [...root.querySelectorAll<HTMLElement>('[data-hold]')],
    show(screen, details) {
      root.dataset.screen = screen
      for (const element of root.querySelectorAll<HTMLElement>('[data-for]'))
        element.hidden = element.dataset.for !== screen
      if (screen === 'end' && time !== null && details?.seconds !== undefined)
        time.textContent = `${details.seconds.toFixed(2)} s`
      root.querySelector<HTMLElement>(`[data-for="${screen}"] .primary`)?.focus()
    },
  }
}

