  '#........#',
  '#.......G#',
  '##########',
])
const OPEN = room([
  '##########',
  ...Array.from({ length: 10 }, () => '#........#'),
  '#P......G#',
  '##########',
])
const LOW_CEILING = room([
  '##########',
  '#........#',
  '#........#',
  '#.####...#',
  '#........#',
  '#........#',
  '#.P.....G#',
  '##########',
])

const NONE: MoveInput = { x: 0, jump: false }
const RIGHT: MoveInput = { x: 1, jump: false }
const JUMP: MoveInput = { x: 0, jump: true }

/** Steps the sim once per input, collecting every event with the tick it happened on. */
function drive(sim: Sim, inputs: readonly MoveInput[]): Array<SimEvent & { tick: number }> {
  const events: Array<SimEvent & { tick: number }> = []
  for (const input of inputs) {
    const result = sim.step([moveCommand(sim, input)])
    expect(result.rejected).toEqual([])
    for (const event of result.events) events.push({ ...event, tick: result.tick })
  }
  return events
}

// Koota allows 16 worlds at once, so every test's sims are disposed after it.
const live: Sim[] = []
afterEach(() => {
  for (const sim of live.splice(0)) sim.dispose()
})
async function make(options: Parameters<typeof createBaseSim>[0]): Promise<Sim> {
  const sim = await createBaseSim(options)
  live.push(sim)
  return sim
}

const repeat = (input: MoveInput, ticks: number): MoveInput[] => Array.from({ length: ticks }, () => input)
const pixel = (subpixels: number) => Math.floor(subpixels / SUB)

/** No tile the hitbox covers is solid. */
function overlapsSolid(sim: Sim, source: RoomSource): boolean {
  const parsed = parseRoom(source)
  const p = readPlayer(sim)
  const left = pixel(p.x)
  const top = pixel(p.y)
  for (let y = top; y < top + HITBOX_H; y++)
    for (let x = left; x < left + HITBOX_W; x++)
      if (parsed.rows[Math.floor(y / 8)]?.charAt(Math.floor(x / 8)) === '#') return true
  return false
}

describe('the character on the ground', () => {
  it('starts at P, standing on the floor', async () => {
    const sim = await make({ room: CORRIDOR })
    drive(sim, [NONE])
    const p = readPlayer(sim)
    expect(pixel(p.x)).toBe(8)
    expect(pixel(p.y) + HITBOX_H).toBe(32) // feet on top of row 4
    expect(p.grounded).toBe(true)
    expect(p.vy).toBe(0)
    expect(sim.query(Player)).toHaveLength(1)
  })

  it('accelerates to max run speed and no further', async () => {
    const sim = await make({ room: ROOM })
    drive(sim, repeat(RIGHT, 30))
    expect(readPlayer(sim).vx).toBe(MAX_RUN)
    expect(readPlayer(sim).facing).toBe(1)
  })

  it('slows to a stop when the input is released', async () => {
    const sim = await make({ room: ROOM })
    drive(sim, repeat(RIGHT, 30))
    drive(sim, repeat(NONE, 30))
    const stopped = readPlayer(sim)
    expect(stopped.vx).toBe(0)
    drive(sim, repeat(NONE, 5))
    expect(readPlayer(sim).x).toBe(stopped.x)
  })

  it('faces left after moving left', async () => {
    const sim = await make({ room: ROOM })
    drive(sim, repeat({ x: -1, jump: false }, 3))
    expect(readPlayer(sim).facing).toBe(-1)
  })

  it('stops flush against a wall and never overlaps it', async () => {
    const tight = room(['######', '#...##', '#P.G##', '######'])
    const sim = await make({ room: tight })
    for (let tick = 0; tick < 60; tick++) {
      drive(sim, [RIGHT])
      expect(overlapsSolid(sim, tight)).toBe(false)
    }
    const p = readPlayer(sim)
    expect(pixel(p.x) + HITBOX_W).toBe(32) // the wall starts at column 4, pixel 32
    expect(p.vx).toBe(0)
  })
})

describe('falling and jumping', () => {
  it('falls, capped at max fall speed, and lands once', async () => {
    const sim = await make({ room: HIGH_START })
    const events = drive(sim, repeat(NONE, 90))
    const landings = events.filter((event) => event.type === 'player.landed')
    expect(landings).toHaveLength(1)
    const p = readPlayer(sim)
    expect(p.grounded).toBe(true)
    expect(pixel(p.y) + HITBOX_H).toBe(72) // the floor is row 9
  })

  it('never falls faster than max fall', async () => {
    const sim = await make({
      room: room(['####', '#..#', '#P.#', ...Array.from({ length: 40 }, () => '#..#'), '#.G#', '####']),
    })
    for (let tick = 0; tick < 60; tick++) {
      drive(sim, [NONE])
      expect(readPlayer(sim).vy).toBeLessThanOrEqual(MAX_FALL)
    }
    expect(readPlayer(sim).vy).toBe(MAX_FALL)
  })

  it('jumps from the floor', async () => {
    const sim = await make({ room: CORRIDOR })
    drive(sim, [NONE])
    const before = readPlayer(sim)
    const events = drive(sim, [JUMP])
    expect(events.map((event) => event.type)).toEqual(['player.jumped'])
    expect(readPlayer(sim).vy).toBe(JUMP_SPEED)
    expect(readPlayer(sim).y).toBeLessThan(before.y)
    expect(readPlayer(sim).grounded).toBe(false)
  })

  it('jumps higher while jump is held than when it is tapped', async () => {
    const apex = async (held: number) => {
      const sim = await make({ room: OPEN })
      drive(sim, [NONE])
      let highest = readPlayer(sim).y
      for (let tick = 0; tick < 60; tick++) {
        drive(sim, [tick < held ? JUMP : NONE])
        highest = Math.min(highest, readPlayer(sim).y)
      }
      return readPlayer(sim).y - highest
    }
    const tapped = await apex(1)
    const held = await apex(30)
    expect(held).toBeGreaterThan(tapped * 2)
    // A held jump clears three tiles (the room's platform step), a tap does not.
    expect(pixel(held)).toBeGreaterThanOrEqual(24)
    expect(pixel(tapped)).toBeLessThan(24)
  })

  it('cannot jump again in mid-air', async () => {
    const sim = await make({ room: OPEN })
    drive(sim, [NONE])
    const events = drive(sim, [JUMP, NONE, NONE, JUMP, NONE, JUMP])
    expect(events.filter((event) => event.type === 'player.jumped')).toHaveLength(1)
  })

  it('remembers a jump pressed just before landing (jump buffer)', async () => {
    const landingTick = async () => {
      const sim = await make({ room: HIGH_START })
      const events = drive(sim, repeat(NONE, 90))
      return events.find((event) => event.type === 'player.landed')?.tick ?? -1
    }
    const landsAt = await landingTick()
    const jumpPressedAt = async (tick: number) => {
      const sim = await make({ room: HIGH_START })
      // Ticks are counted from 1 (the tick a step ends on); press on one tick, then let go.
      const inputs = Array.from({ length: 90 }, (_, i) => (i + 1 === tick ? JUMP : NONE))
      return drive(sim, inputs).filter((event) => event.type === 'player.jumped')
    }
    // The landing happens during the move at the end of a tick, so the buffered jump fires on the next one.
    const buffered = await jumpPressedAt(landsAt - 3)
    expect(buffered.map((event) => event.tick)).toEqual([landsAt + 1])
    expect(await jumpPressedAt(landsAt - 8)).toEqual([])
  })

  it('still jumps just after walking off a ledge (coyote time), but not later', async () => {
    const leftGroundAt = async () => {
      const sim = await make({ room: LEDGE })
      for (let tick = 1; tick < 120; tick++) {
        drive(sim, [RIGHT])
        if (!readPlayer(sim).grounded) return tick
      }
      return -1
    }
    const offAt = await leftGroundAt()
    expect(offAt).toBeGreaterThan(0)
    const jumpAt = async (tick: number) => {
      const sim = await make({ room: LEDGE })
      const inputs = Array.from({ length: tick + 2 }, (_, i) => ({ x: 1, jump: i + 1 === tick }) as const)
      return drive(sim, inputs).filter((event) => event.type === 'player.jumped')
    }
    expect(await jumpAt(offAt + 4)).toHaveLength(1)
    expect(await jumpAt(offAt + 8)).toHaveLength(0)
  })

  it('stops rising when its head hits a ceiling', async () => {
    const sim = await make({ room: LOW_CEILING })
    drive(sim, [NONE])
    for (let tick = 0; tick < 20; tick++) {
      drive(sim, [JUMP])
      expect(overlapsSolid(sim, LOW_CEILING)).toBe(false)
    }
    // Head against the underside of row 3 (pixel 32), then falling again.
    expect(pixel(readPlayer(sim).y)).toBeGreaterThanOrEqual(32)
    drive(sim, repeat(NONE, 40))
    expect(readPlayer(sim).grounded).toBe(true)
  })
})

describe('the goal', () => {
  it('fires once when the character touches the goal', async () => {
    const sim = await make({ room: CORRIDOR })
    const events = drive(sim, repeat(RIGHT, 120))
    const reached = events.filter((event) => event.type === 'goal.reached')
    expect(reached).toHaveLength(1)
    expect(sim.resource(Progress).reached).toBe(true)
  })

  it('has not fired at the start', async () => {
    const sim = await make({ room: CORRIDOR })
    drive(sim, [NONE])
    expect(sim.resource(Progress).reached).toBe(false)
  })
})

import { defineSystem, type SystemDef } from '@mcthaydt/automata-sim'
import { Move } from './move.command.ts'
import { PlayerControl } from './player.component.ts'

/** Copies this tick's `move` command onto the character. No command means nothing is held. */
export const playerInput: SystemDef = defineSystem({
  name: 'player.input',
  phase: 'input',
  run(ctx) {
    const commands = ctx.commands.of(Move)
    const last = commands[commands.length - 1]
    const moveX = last === undefined ? 0 : last.payload.x
    const jump = last === undefined ? false : last.payload.jump
    for (const entity of ctx.query(PlayerControl)) {
      const control = entity.get(PlayerControl)
      entity.set(PlayerControl, { moveX, jumpHeld: jump, jumpPressed: jump && !control.jumpHeld })
    }
  },
})

import { defineSystem, type SystemDef } from '@mcthaydt/automata-sim'
import { Player, PlayerControl } from './player.component.ts'
import { Jumped, Landed } from './player.event.ts'
import { hitsSolid, type RoomGrid, roomOf } from './tiles.ts'
import {
  AIR_ACCEL,
  BUFFER_TICKS,
  COYOTE_TICKS,
  GRAVITY,
  HALF_GRAVITY_BELOW,
  JUMP_SPEED,
  MAX_FALL,
  MAX_RUN,
  RUN_ACCEL,
  SUB,
  VAR_JUMP_TICKS,
} from './tuning.ts'

/**
 * Runs, jumps and collides the character, in Celeste's order: read the ground, set the jump timers, run,
 * fall, keep or cut a held jump, start a jump, then move one axis at a time.
 */
export const playerMove: SystemDef = defineSystem({
  name: 'player.move',
  phase: 'physics',
  run(ctx) {
    const room = roomOf(ctx.content)
    for (const entity of ctx.query(Player, PlayerControl)) {
      const p = { ...entity.get(Player) }
      const c = { ...entity.get(PlayerControl) }
      const onGround = standingOnSolid(room, p.x, p.y)

      // Coyote time: a jump stays possible for a few ticks after leaving the ground.
      if (onGround) c.coyote = COYOTE_TICKS
      else if (c.coyote > 0) c.coyote -= 1

      // Run toward the held direction; with nothing held, toward a stop. Slower to change in the air.
      if (c.moveX !== 0) p.facing = c.moveX
      p.vx = approach(p.vx, MAX_RUN * c.moveX, onGround ? RUN_ACCEL : AIR_ACCEL)

      // Fall. Near the top of a held jump gravity halves, which gives the jump its float.
      if (!onGround) {
        const half = c.jumpHeld && abs(p.vy) < HALF_GRAVITY_BELOW
        p.vy = approach(p.vy, MAX_FALL, half ? GRAVITY / 2 : GRAVITY)
      }

      // A held jump keeps its full speed for a while; letting go ends that early (variable jump height).
      if (c.varJump > 0) {
        if (c.jumpHeld) p.vy = Math.min(p.vy, JUMP_SPEED)
        else c.varJump = 0
      }

      // Jump buffer: a press is remembered for a few ticks, so pressing just before landing still jumps.
      if (c.jumpPressed) c.buffer = BUFFER_TICKS
      if (c.buffer > 0 && c.coyote > 0) {
        p.vy = JUMP_SPEED
        c.varJump = VAR_JUMP_TICKS
        c.buffer = 0
        c.coyote = 0
        ctx.emit(Jumped, { x: pixel(p.x), y: pixel(p.y) })
      } else if (c.buffer > 0) {
        c.buffer -= 1
      }
      if (c.varJump > 0) c.varJump -= 1

      const movedX = slide(room, p.x, p.y, p.vx, 'x')
      p.x = movedX.position
      if (movedX.hit) p.vx = 0

      const movedY = slide(room, p.x, p.y, p.vy, 'y')
      p.y = movedY.position
      if (movedY.hit) {
        if (p.vy < 0) c.varJump = 0 // head against a ceiling
        p.vy = 0
      }

      // Landing is the change from airborne to standing, whether the fall ended exactly on the floor's top
      // pixel or was stopped by it.
      p.grounded = standingOnSolid(room, p.x, p.y)
      if (p.grounded && p.vy > 0) p.vy = 0
      if (p.grounded && !onGround) ctx.emit(Landed, { x: pixel(p.x), y: pixel(p.y) })
      entity.set(Player, p)
      entity.set(PlayerControl, c)
    }
  },
})

function pixel(subpixels: number): number {
  return Math.floor(subpixels / SUB)
}

function abs(value: number): number {
  return value < 0 ? -value : value
}

/** Moves `value` toward `target` by at most `step`. */
function approach(value: number, target: number, step: number): number {
  return value < target ? Math.min(value + step, target) : Math.max(value - step, target)
}

function standingOnSolid(room: RoomGrid, x: number, y: number): boolean {
  return hitsSolid(room, pixel(x), pixel(y) + 1)
}

/**
 * Moves along one axis by `amount` subpixels, at most one pixel at a time, stopping at the first pixel that
 * would overlap a solid tile. A stop leaves the hitbox pressed against the tile: on the last subpixel of its
 * pixel when moving right or down, on the first when moving left or up. One pixel at a time means nothing can
 * pass through a wall, whatever its speed.
 */
function slide(
  room: RoomGrid,
  x: number,
  y: number,
  amount: number,
  axis: 'x' | 'y',
): { position: number; hit: boolean } {
  let position = axis === 'x' ? x : y
  let remaining = amount
  while (remaining !== 0) {
    const step = remaining > 0 ? Math.min(remaining, SUB) : Math.max(remaining, -SUB)
    const next = position + step
    const blocked =
      axis === 'x' ? hitsSolid(room, pixel(next), pixel(y)) : hitsSolid(room, pixel(x), pixel(next))
    if (blocked) {
      const pixelStart = pixel(position) * SUB
      return { position: step > 0 ? pixelStart + SUB - 1 : pixelStart, hit: true }
    }
    position = next
    remaining -= step
  }
  return { position, hit: false }
}

import { type ComponentDef, defineComponent } from '@mcthaydt/automata-sim'

const playerFields = { x: 'i32', y: 'i32', vx: 'i32', vy: 'i32', facing: 'i32', grounded: 'bool' } as const

/**
 * The character, as the renderer sees it. `x`, `y` are the hitbox's top-left corner and `vx`, `vy` its speed,
 * in subpixels (tuning.ts); `facing` is 1 (right) or -1 (left).
 */
export const Player: ComponentDef<typeof playerFields> = defineComponent('player', playerFields)

const controlFields = {
  moveX: 'i32',
  jumpHeld: 'bool',
  jumpPressed: 'bool',
  coyote: 'u32',
  buffer: 'u32',
  varJump: 'u32',
} as const

/**
 * This tick's input and the jump timers, in ticks left. Not rendered. `jumpPressed` is true only on the tick
 * jump goes down, so holding it does not jump again on landing.
 */
export const PlayerControl: ComponentDef<typeof controlFields> = defineComponent(
  'player-control',
  controlFields,
  {
    render: false,
  },
)

import { defineEvent, type EventDef } from '@mcthaydt/automata-sim'
import { z } from 'zod'

// Where something happened, in whole pixels (the hitbox's top-left corner). The renderer uses these for
// squash and stretch and dust; the page uses goal.reached to end the round.
const at = z.object({ x: z.number().int(), y: z.number().int() })

export const Jumped: EventDef<typeof at> = defineEvent('player.jumped', at)
export const Landed: EventDef<typeof at> = defineEvent('player.landed', at)
export const GoalReached: EventDef<typeof at> = defineEvent('goal.reached', at)

import { defineResource, type ResourceDef } from '@mcthaydt/automata-sim'
import { z } from 'zod'

const progressSchema = z.object({ reached: z.boolean(), tick: z.number().int() })

/** Whether the goal has been reached, and on which tick. */
export const Progress: ResourceDef<typeof progressSchema> = defineResource(
  'progress',
  progressSchema,
  () => ({
    reached: false,
    tick: 0,
  }),
)

// The room as the sim sees it: the content passed to createSim, read without copying. Shared with
// `src/content/room.ts`, so the sim and the content agree on what is solid.
import { HITBOX_H, HITBOX_W } from './tuning.ts'

export interface TilePosition {
  readonly tx: number
  readonly ty: number
}

export interface RoomGrid {
  readonly tileSize: number
  readonly width: number
  readonly height: number
  readonly rows: readonly string[]
  readonly start: TilePosition
  readonly goal: TilePosition
}

/** Whether a tile blocks movement. Outside the room counts as solid, so nothing can leave it. */
export function isSolid(room: RoomGrid, tx: number, ty: number): boolean {
  if (tx < 0 || ty < 0 || tx >= room.width || ty >= room.height) return true
  return room.rows[ty]?.charAt(tx) === '#'
}

/** Whether a hitbox with its top-left corner at pixel (px, py) covers the given kind of tile anywhere. */
export function hitboxTouches(
  room: RoomGrid,
  px: number,
  py: number,
  test: (tx: number, ty: number) => boolean,
): boolean {
  const left = Math.floor(px / room.tileSize)
  const right = Math.floor((px + HITBOX_W - 1) / room.tileSize)
  const top = Math.floor(py / room.tileSize)
  const bottom = Math.floor((py + HITBOX_H - 1) / room.tileSize)
  for (let ty = top; ty <= bottom; ty++) for (let tx = left; tx <= right; tx++) if (test(tx, ty)) return true
  return false
}

/** Whether the hitbox at pixel (px, py) overlaps a solid tile. */
export function hitsSolid(room: RoomGrid, px: number, py: number): boolean {
  return hitboxTouches(room, px, py, (tx, ty) => isSolid(room, tx, ty))
}

/**
 * The room inside the sim's content. The content is frozen JSON, typed `unknown` by the sim, so this checks
 * its shape once per use rather than trusting a cast; a wrong shape is a setup bug and throws.
 */
export function roomOf(content: unknown): RoomGrid {
  const room = (content as { room?: RoomGrid } | null)?.room
  if (
    room === undefined ||
    typeof room.tileSize !== 'number' ||
    typeof room.width !== 'number' ||
    typeof room.height !== 'number' ||
    !Array.isArray(room.rows) ||
    typeof room.goal?.tx !== 'number' ||
    typeof room.start?.tx !== 'number'
  )
    throw new Error('base-2d: the sim content has no room')
  return room
}

// How the character moves. Celeste's published constants (Maddy Thorson, `Player.cs`, 2018), converted from
// pixels per second to the sim's units: subpixels (SUB per pixel) per tick at 60 ticks a second. Integers keep
// every step exact in every engine. Each comment gives the original value.

/** Subpixels per pixel. Positions and speeds are whole numbers of these. */
export const SUB = 256
export const TICK_HZ = 60

/** The character's hitbox in pixels: smaller than its 16 × 16 sprite, as in Celeste, so corners forgive. */
export const HITBOX_W = 8
export const HITBOX_H = 12

/** 90 px/s. */
export const MAX_RUN = 384
/** 1000 px/s², on the ground. */
export const RUN_ACCEL = 71
/** RUN_ACCEL × 0.65 in the air (AirMult). */
export const AIR_ACCEL = 46

/** 900 px/s², only while airborne. */
export const GRAVITY = 64
/** Gravity halves near the top of a jump while jump is held: below 40 px/s of vertical speed. */
export const HALF_GRAVITY_BELOW = 171
/** 160 px/s. */
export const MAX_FALL = 683

/** −105 px/s (up is negative). */
export const JUMP_SPEED = -448
/** 0.2 s: how long holding jump keeps the full jump speed (VarJumpTime). */
export const VAR_JUMP_TICKS = 12
/** 0.1 s: a jump still works this long after walking off a ledge (JumpGraceTime). */
export const COYOTE_TICKS = 6
/** About 0.08 s: a jump pressed this long before landing still happens. */
export const BUFFER_TICKS = 5

/* Colors are Endesga 64 (src/art/palette.ts). Contrast: --text on --panel is about 13:1, --ink on --accent
   about 14:1, and the --focus ring on --panel about 12:1. The type is Pixelify Sans (OFL, bundled), drawn
   with hard offset shadows and no blur, so the interface reads as part of the pixel art. */
:root {
  --bg: #0e071b;
  --panel: #1a1932;
  --panel-edge: #03193f;
  --text: #f9e6cf;
  --muted: #c7cfdd;
  --accent: #ffc825;
  --accent-lit: #ffeb57;
  --accent-shade: #e07438;
  --ember: #ff5000;
  --ink: #0e071b;
  --focus: #0cf1ff;
  --line: #424c6e;
  --pixel-font: "Pixelify Sans", system-ui, sans-serif;
}

html,
body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font: 16px / 1.4 var(--pixel-font);
  overscroll-behavior: none;
}

#game {
  position: relative;
  height: 100dvh;
  box-sizing: border-box;
  padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom)
    env(safe-area-inset-left);
  overflow: hidden;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.stage-box {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
}

.stage {
  image-rendering: pixelated;
}

/* Overlays fill the game's container and centre their panel over a dimmed, darker-at-the-edges game. */
.panel {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: max(16px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right))
    max(16px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left));
  background: radial-gradient(
    ellipse at center,
    color-mix(in srgb, var(--bg) 45%, transparent),
    color-mix(in srgb, var(--bg) 88%, transparent)
  );
  text-align: center;
}

.panel[hidden],
.hud[hidden],
.touch[hidden] {
  display: none;
}

.panel h1,
.panel h2,
.panel p {
  margin: 0;
}

.panel h2 {
  font-size: 28px;
  font-weight: 700;
  text-shadow: 0 3px 0 var(--panel-edge);
}

/* The title: warm letters with a stepped ember shadow below them. */
.title {
  font-size: 56px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.02em;
  color: var(--accent-lit);
  text-shadow:
    0 3px 0 var(--accent),
    0 6px 0 var(--accent-shade),
    0 9px 0 var(--ember),
    0 12px 0 var(--panel-edge);
}

/* More specific than `.panel h1`, which zeroes the margin. */
.panel .title {
  margin-bottom: 6px;
}

.mark {
  font-size: 30px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--accent-lit);
  text-shadow: 0 3px 0 var(--accent-shade);
}

.hint,
.time {
  color: var(--muted);
}

.time {
  font-size: 40px;
  font-weight: 700;
  color: var(--accent-lit);
  text-shadow: 0 3px 0 var(--accent-shade);
}

.blink {
  animation: blink 1.2s steps(2, jump-none) infinite;
}

@keyframes blink {
  50% {
    opacity: 0.35;
  }
