import { defineShipConfig } from '@mcthaydt/automata-ship'
import packageJson from './package.json' with { type: 'json' }

export default defineShipConfig({
  game: {
    id: 'demo-physics-bodies-2d',
    title: 'AF demo: physics bodies 2D',
    version: packageJson.version,
    entry: 'index.html',
    sdk: '^0.0.0',
  },
  runtime: { renderer: 'webgl2', orientation: 'any', inputs: ['touch', 'keyboard'], pause_behavior: 'pause' },
  network: { connect: [] },
  content: { languages: ['en'], rating: 'everyone', descriptors: [] },
})

// The demo's sim half: Rapier bodies in base-2d's room, through @mcthaydt/automata-physics/2d.
//
// Three kinds of body:
// - fixed: the room's solid tiles, one cuboid per run of `#` in a row (fewer bodies than one per tile);
// - kinematic: an invisible box that follows Wick, so Wick shoves bodies around (Wick still moves by the
//   base's own tile collision; physics never moves Wick);
// - dynamic: crates and stones, a few to start and one more per `drop` command.
//
// Units: physics works in metres with y up; the room is in pixels with y down. 16 pixels are a metre, so a tile
// is half a metre and the room 20 × 12 m. Everything here runs inside the sim: no I/O, no clock, no
// randomness, so the same drops give the same pile in every browser (bodies.parity.test.ts). `pnpm boundaries`
// checks this folder; it imports only the sim, the physics extension and the base's sim
// (`@af-examples/base-2d/sim`), never the base's package root, which reaches the host bridge.
import { isSolid, Player, type RoomGrid, tuning } from '@af-examples/base-2d/sim'
import {
  BodyKind,
  body2d,
  collider2d,
  RigidBody2D,
  Transform2D,
  transform2d,
} from '@mcthaydt/automata-physics/2d'
import {
  defineCommand,
  defineComponent,
  definePlugin,
  defineSystem,
  type PluginDef,
  type SpawnPart,
} from '@mcthaydt/automata-sim'
import { z } from 'zod'

export const PX_PER_M = 16
/** Stronger than Earth's 9.81, so 8-pixel crates fall as briskly as Wick does. */
export const GRAVITY = -40
/** Past this many loose bodies, the oldest is removed to make room for a new drop. */
export const MAX_LOOSE = 40

/** Marks the kinematic box that follows Wick; `player` is the player slot it follows (always 0 here). */
export const Follower = defineComponent('bodies.follower', { player: 'u32' })

/** What a loose body looks like: the renderer draws a crate or a stone from this. */
export const PropKind = { crate: 0, stone: 1 } as const
/**
 * Rendered, unlike RigidBody2D and Collider2D: it is how the drawing layer, which sees only the sim's
 * RenderDelta, tells a crate from a stone (and a loose body from a wall).
 */
export const Prop = defineComponent('bodies.prop', { kind: 'u32' })

/** Drop a body just above Wick: a crate on even ticks, a stone on odd ones. */
export const Drop = defineCommand('bodies.drop', z.object({}))

/** Room pixels to metres, for a point (y flips). */
export const metresX = (px: number) => px / PX_PER_M
export const metresY = (py: number, roomHeightPx: number) => (roomHeightPx - py) / PX_PER_M

export const crate = (x: number, y: number): SpawnPart[] => [
  transform2d({ x, y }),
  body2d(BodyKind.dynamic, { angularDamping: 0.5 }),
  collider2d.cuboid(0.25, 0.25, { friction: 0.8 }),
  [Prop, { kind: PropKind.crate }],
]
export const stone = (x: number, y: number): SpawnPart[] => [
  transform2d({ x, y }),
  body2d(BodyKind.dynamic, { angularDamping: 0.2 }),
  collider2d.ball(0.22, { friction: 0.6, restitution: 0.45 }),
  [Prop, { kind: PropKind.stone }],
]

/** Where Wick's hitbox centre is, in metres. */
export function wickCentre(player: { x: number; y: number }, roomHeightPx: number) {
  const px = player.x / tuning.SUB + tuning.HITBOX_W / 2
  const py = player.y / tuning.SUB + tuning.HITBOX_H / 2
  return { x: metresX(px), y: metresY(py, roomHeightPx) }
}

/** How high above Wick's centre a drop starts. */
export const DROP_ABOVE = 1.25

/**
 * Where a drop starts: `DROP_ABOVE` over Wick, or, if that spot is inside a platform (Wick walks under them),
 * a tile higher at a time until it is clear, so Rapier never has to push a body out of a wall.
 */
export function dropHeight(room: RoomGrid, x: number, wickY: number): number {
  const heightPx = room.height * room.tileSize
  const half = 0.25 // a crate's half size, and a little more than a stone's radius
  const tileM = room.tileSize / PX_PER_M
  let y = wickY + DROP_ABOVE
  while (y < heightPx / PX_PER_M && boxTouchesSolid(room, x, y, half)) y += tileM
  return y
}

function boxTouchesSolid(room: RoomGrid, x: number, y: number, half: number): boolean {
  const heightPx = room.height * room.tileSize
  // The box's edges in room pixels (y down). The right and bottom edges are exclusive, so a box that only
  // touches a tile's edge does not count as inside it.
  const left = Math.floor(((x - half) * PX_PER_M) / room.tileSize)
  const right = Math.ceil(((x + half) * PX_PER_M) / room.tileSize) - 1
  const top = Math.floor((heightPx - (y + half) * PX_PER_M) / room.tileSize)
  const bottom = Math.ceil((heightPx - (y - half) * PX_PER_M) / room.tileSize) - 1
  for (let ty = top; ty <= bottom; ty++)
    for (let tx = left; tx <= right; tx++) if (isSolid(room, tx, ty)) return true
  return false
}

export function bodiesPlugin(room: RoomGrid): PluginDef {
  const roomHeightPx = room.height * room.tileSize
  return definePlugin({
    name: 'bodies-2d-demo',
    commands: [Drop],
    systems: [
      defineSystem({
        name: 'bodies.drop',
        phase: 'input',
        run(ctx) {
          const [wick] = ctx.query(Player)
          if (wick === undefined) return
          for (const _ of ctx.commands.of(Drop)) {
            const loose = ctx
              .query(RigidBody2D)
              .filter((body) => body.get(RigidBody2D).kind === BodyKind.dynamic)
            // Bodies come back in ascending id order, so the first is the oldest.
            const oldest = loose[0]
            if (loose.length >= MAX_LOOSE && oldest !== undefined) ctx.despawn(oldest.sid)
            const at = wickCentre(wick.get(Player), roomHeightPx)
            // A small sideways nudge that changes with the tick, so drops on one spot topple into a pile
            // instead of balancing in a perfect column.
            const x = at.x + ((ctx.tick % 5) - 2) * 0.05
            const y = dropHeight(room, x, at.y)
            const parts = ctx.tick % 2 === 0 ? crate(x, y) : stone(x, y)
            ctx.spawn(...parts)
          }
        },
      }),
      defineSystem({
        // After the base has moved Wick this tick; the physics step picks the new position up next tick.
        name: 'bodies.follow-wick',
        phase: 'postPhysics',
        run(ctx) {
          const [wick] = ctx.query(Player)
          const [follower] = ctx.query(Transform2D, Follower)
          if (wick === undefined || follower === undefined) return
          follower.set(Transform2D, wickCentre(wick.get(Player), roomHeightPx))
        },
      }),
    ],
    components: [Follower, Prop],
  })
}

import { moveCommand, ROOM } from '@af-examples/base-2d'
import { BodyKind, RigidBody2D, Transform2D } from '@mcthaydt/automata-physics/2d'
import type { Command, Sim } from '@mcthaydt/automata-sim'
import { afterEach, describe, expect, it } from 'vitest'
import { createBodiesSim } from '../bodies-sim.ts'
import { DROP_ABOVE, Drop, Follower, MAX_LOOSE, Prop, PropKind } from './bodies.plugin.ts'

const sims: Sim[] = []
afterEach(() => {
  for (const sim of sims.splice(0)) sim.dispose()
})
const make = async () => {
  const sim = await createBodiesSim(ROOM)
  sims.push(sim)
  return sim
}

const drop = (sim: Sim): Command => ({
  tick: sim.tick,
  source: 0,
  seq: 0x80000000 + sim.tick,
  type: Drop.id,
  payload: {},
})
const loose = (sim: Sim) =>
  sim.query(RigidBody2D).filter((body) => body.get(RigidBody2D).kind === BodyKind.dynamic)

/** Runs `ticks` steps with Wick holding `x` and the given drops on the given ticks. */
function run(sim: Sim, ticks: number, x: -1 | 0 | 1 = 0, dropOn: readonly number[] = []) {
  for (let i = 0; i < ticks; i++) {
    const commands = [moveCommand(sim, { x, jump: false })]
    if (dropOn.includes(sim.tick)) commands.push(drop(sim))
    const result = sim.step(commands)
    expect(result.rejected).toEqual([])
  }
}

describe('bodies in the room', () => {
  it('starts with four crates and three stones, which fall and come to rest', async () => {
    const sim = await make()
    expect(loose(sim)).toHaveLength(7)
    const heights = () => loose(sim).map((body) => body.get(Transform2D).y)
    const start = heights()
    run(sim, 180)
    const settled = heights()
    run(sim, 30)
    expect(settled.some((y, i) => y < (start[i] as number) - 0.1)).toBe(true)
    // Resting: nothing moves more than a hair in another half second.
    for (const [i, y] of heights().entries()) expect(Math.abs(y - (settled[i] as number))).toBeLessThan(0.02)
    // Nothing fell through the floor (its top is half a metre up).
    for (const y of heights()) expect(y).toBeGreaterThan(0.5)
  })

  it('drops a body above Wick, and the box that follows Wick moves with Wick', async () => {
    const sim = await make()
    const follower = () =>
      (sim.query(Transform2D, Follower)[0] as NonNullable<ReturnType<Sim['entity']>>).get(Transform2D)
    const before = follower().x
    run(sim, 40, 1, [5])
    expect(loose(sim)).toHaveLength(8)
    expect(follower().x).toBeGreaterThan(before + 0.5)
  })

  it(`keeps at most ${MAX_LOOSE} loose bodies, removing the oldest`, async () => {
    const sim = await make()
    const first = loose(sim)[0]?.sid
    run(
      sim,
      MAX_LOOSE,
      0,
      Array.from({ length: MAX_LOOSE }, (_, i) => i),
    )
    expect(loose(sim)).toHaveLength(MAX_LOOSE)
    expect(loose(sim).map((body) => body.sid)).not.toContain(first)
  })

  it('lets Wick shove the crate stack to the right', async () => {
    const sim = await make()
    const crates = () => loose(sim).filter((body) => body.get(Prop).kind === PropKind.crate)
    run(sim, 60) // let the stack settle first
    const before = Math.max(...crates().map((body) => body.get(Transform2D).x))
    run(sim, 90, 1)
    const after = Math.max(...crates().map((body) => body.get(Transform2D).x))
    expect(after).toBeGreaterThan(before + 0.25)
  })

  it('tags every loose body with what it looks like, and sends that to the renderer', async () => {
    const sim = await make()
    const kinds = loose(sim).map((body) => body.get(Prop).kind)
    expect(kinds.filter((kind) => kind === PropKind.crate)).toHaveLength(4)
    expect(kinds.filter((kind) => kind === PropKind.stone)).toHaveLength(3)
    // The first step's delta is a resync listing every rendered entity; the loose bodies come with their
    // Prop and Transform2D (RigidBody2D and Collider2D are not rendered, so the layer cannot tell them apart).
    const result = sim.step([moveCommand(sim, { x: 0, jump: false })])
    const props = result.render.added.filter((row) => row.components[Prop.id] !== undefined)
    expect(props).toHaveLength(7)
    for (const row of props) expect(row.components[Transform2D.id]).toBeDefined()
  })

  /** Drops one body on the next tick and returns where it is after that step, with Wick's centre before it. */
  function dropOne(sim: Sim) {
    const wick = (sim.query(Transform2D, Follower)[0] as NonNullable<ReturnType<Sim['entity']>>).get(
      Transform2D,
    )
    const ids = new Set(loose(sim).map((body) => body.sid))
    run(sim, 1, 0, [sim.tick])
    const dropped = loose(sim).find((body) => !ids.has(body.sid))
    if (dropped === undefined) throw new Error('nothing dropped')
    return { wick, at: dropped.get(Transform2D) }
  }

  it(`drops the new body ${DROP_ABOVE} m above Wick where nothing is in the way`, async () => {
    const sim = await make()
    run(sim, 60, -1) // to the left wall, where no platform hangs over Wick
    run(sim, 2) // stop, and let the box that follows Wick catch up
    const { wick, at } = dropOne(sim)
    expect(wick.x).toBeLessThan(1)
    // One step of gravity has already pulled it down a hair.
    expect(at.y).toBeGreaterThan(wick.y + DROP_ABOVE - 0.05)
    expect(at.y).toBeLessThanOrEqual(wick.y + DROP_ABOVE)
  })

  it('drops it above the platform instead when Wick stands under one', async () => {
    const sim = await make()
    run(sim, 2)
    // At the start Wick is under the low platform (row 20, its top 2 m up): 1.25 m above him is inside it.
    const { wick, at } = dropOne(sim)
    expect(wick.y + DROP_ABOVE).toBeLessThan(2.25)
    expect(at.y).toBeGreaterThan(wick.y + DROP_ABOVE + 0.45)
    expect(at.y).toBeLessThanOrEqual(wick.y + DROP_ABOVE + 0.5)
  })

  it('gives the same pile for the same drops', async () => {
    const a = await make()
    const b = await make()
    run(a, 120, 1, [3, 20, 40])
    run(b, 120, 1, [3, 20, 40])
    expect(a.hash()).toBe(b.hash())
  })
})

