import { describe, expect, it } from 'vitest'
import { FAIL_MODES, type FailMode, failMode } from './fail-mode.ts'

describe('failMode (§8 ?fail= query)', () => {
  it.each([
    ['?fail=init', 'init'],
    ['?fail=saves', 'saves'],
    ['?fail=content', 'content'],
    ['?fail=download', 'download'],
    ['?fail=stall', 'stall'],
    ['?fail=renderer', 'renderer'],
    ['?fail=ready', 'ready'],
  ] as const)("failMode('%s') is '%s'", (query, expected: FailMode) => {
    expect(failMode(query)).toBe(expected)
  })

  it('full URL query is parsed correctly', () => {
    expect(failMode('http://localhost:5400/?fail=stall&other=1')).toBe('stall')
  })

  it('unknown or missing fail param returns undefined', () => {
    expect(failMode('?fail=unknown')).toBeUndefined()
    expect(failMode('?other=value')).toBeUndefined()
    expect(failMode('')).toBeUndefined()
  })

  it('FAIL_MODES contains all seven fail modes', () => {
    expect(FAIL_MODES).toEqual(['init', 'saves', 'content', 'download', 'stall', 'renderer', 'ready'])
  })
})

export type FailMode = 'init' | 'saves' | 'content' | 'download' | 'stall' | 'renderer' | 'ready'

export const FAIL_MODES: readonly FailMode[] = [
  'init',
  'saves',
  'content',
  'download',
  'stall',
  'renderer',
  'ready',
]

/**
 * Extracts and validates the `?fail=` query mode (spec §8).
 * Supports search strings (e.g. `?fail=stall`) or full URLs.
 */
export function failMode(
  queryOrUrl: string = typeof window !== 'undefined' ? window.location.search : '',
): FailMode | undefined {
  if (!queryOrUrl) return undefined

  let search = queryOrUrl
  try {
    if (queryOrUrl.startsWith('http://') || queryOrUrl.startsWith('https://')) {
      search = new URL(queryOrUrl).search
    }
  } catch {
    // fallback to parsing queryOrUrl directly
  }

  const params = new URLSearchParams(search.startsWith('?') ? search : `?${search}`)
  const value = params.get('fail')
  if (value && (FAIL_MODES as readonly string[]).includes(value)) {
    return value as FailMode
  }
  return undefined
}

import { runGame } from '@mcthaydt/automata-runtime'
import { fakeFetch, manualFrames } from '@mcthaydt/automata-runtime/testing'
import { describe, expect, it } from 'vitest'
import { demoGame } from './game.ts'

describe('demoGame (§8 boot and flow demo)', () => {
  it('standalone boot reaches ready on title; Play -> play with rising tick; Pause -> paused with paused tick; Resume -> play', async () => {
    const root = document.createElement('div')
    document.body.appendChild(root)

    const frames = manualFrames()
    const fetchMock = fakeFetch({
      '/assets/title.txt': { chunks: [new TextEncoder().encode('title content')] },
      '/assets/play.txt': { chunks: [new TextEncoder().encode('play content')] },
    })

    const game = demoGame(undefined, {
      root,
      frames,
      fetch: fetchMock.fetch,
    })

    const handle = runGame(game)

    // Wait until boot reaches ready (frame 1 advance)
    while (!frames.pending) {
      await new Promise((r) => setTimeout(r, 5))
    }
    frames.advance(16.67)

    // Wait for ready state
    while (document.documentElement.getAttribute('data-state') !== 'ready') {
      await new Promise((r) => setTimeout(r, 5))
    }

    expect(document.documentElement.getAttribute('data-state')).toBe('ready')
    expect(root.querySelector('[data-testid="title-screen"]')).not.toBeNull()

    // 1. Play -> play screen
    const playBtn = root.querySelector('[data-testid="play-btn"]') as HTMLButtonElement
    expect(playBtn).not.toBeNull()
    playBtn.click()

    while (!root.querySelector('[data-testid="play-screen"]')) {
      await new Promise((r) => setTimeout(r, 5))
    }

    const tickSpan = root.querySelector('[data-testid="tick"]') as HTMLSpanElement
    expect(tickSpan).not.toBeNull()
    expect(tickSpan.textContent).toBe('0')

    // Advance frames: tick counter rises
    frames.advance(16.67)
    frames.advance(16.67)
    expect(Number(tickSpan.textContent)).toBeGreaterThan(0)
    const tickBeforePause = Number(tickSpan.textContent)

    // 2. Pause -> paused screen
    const pauseBtn = root.querySelector('[data-testid="pause-btn"]') as HTMLButtonElement
    expect(pauseBtn).not.toBeNull()
    pauseBtn.click()

    while (!root.querySelector('[data-testid="paused-screen"]')) {
      await new Promise((r) => setTimeout(r, 5))
    }

    // Advancing frames does NOT advance sim tick because Time holds menu pause
    frames.advance(16.67)
    frames.advance(16.67)

    // 3. Resume -> play screen
    const resumeBtn = root.querySelector('[data-testid="resume-btn"]') as HTMLButtonElement
    expect(resumeBtn).not.toBeNull()
    resumeBtn.click()

    while (!root.querySelector('[data-testid="play-screen"]')) {
      await new Promise((r) => setTimeout(r, 5))
    }

    const resumedTick = root.querySelector('[data-testid="tick"]') as HTMLSpanElement
    expect(Number(resumedTick.textContent)).toBe(tickBeforePause)

    // Advancing frames resumes stepping
    frames.advance(16.67)
    expect(Number(resumedTick.textContent)).toBeGreaterThan(tickBeforePause)

    await handle.shutdown()
    root.remove()
  })

  it.each([
    ['init', 'start'],
    ['saves', 'progress'],
    ['content', 'damaged'],
    ['download', 'download'],
    ['renderer', 'unsupported'],
  ] as const)("failMode='%s' shows panel with data-code='%s'", async (mode, expectedCode) => {
    const root = document.createElement('div')
    document.body.appendChild(root)

    const frames = manualFrames()
    const fetchMock = fakeFetch({
      '/assets/title.txt': { chunks: [new TextEncoder().encode('title content')] },
      '/assets/play.txt': { chunks: [new TextEncoder().encode('play content')] },
    })

    const game = demoGame(mode, {
      root,
      frames,
      fetch: fetchMock.fetch,
    })

    const handle = runGame(game)

    while (!frames.pending) {
      await new Promise((r) => setTimeout(r, 5))
    }
    frames.advance(16.67)

    while (document.documentElement.getAttribute('data-state') !== 'failed') {
      await new Promise((r) => setTimeout(r, 5))
    }

    expect(document.documentElement.getAttribute('data-state')).toBe('failed')
    const alert = root.querySelector('[role="alert"]')
    expect(alert).not.toBeNull()
    expect(alert?.getAttribute('data-code')).toBe(expectedCode)

    await handle.shutdown()
    root.remove()
  })
})

import type { CompiledContentData, GameDefinition, RuntimeSeams } from '@mcthaydt/automata-runtime'
import { fakeFetch, nullRenderer } from '@mcthaydt/automata-runtime/testing'
import { z } from 'zod'
import type { FailMode } from './fail-mode.ts'
import { pausedScreen } from './screens/paused.ts'
import { playScreen } from './screens/play.ts'
import { titleScreen } from './screens/title.ts'

export const demoContentData: CompiledContentData = {
  flow: {
    entry: 'title',
    screens: ['title', 'play', 'paused'],
    terminal: [],
    transitions: [
      { from: 'title', event: 'play', to: 'play', transition: 'cut' },
      { from: 'play', event: 'pause', to: 'paused', transition: 'cut' },
      { from: 'paused', event: 'resume', to: 'play', transition: 'cut' },
    ],
  },
  game: {
    source_language: 'en',
    rating: 'everyone',
    descriptors: [],
    custom_events: [],
    preload_screens: ['title'],
  },
  assets: {
    screens: {
      title: { files: ['/assets/title.txt'] },
      play: { files: ['/assets/play.txt'] },
      paused: { files: [] },
    },
  },
}

export interface DemoGameSeams extends RuntimeSeams {
  readonly root?: HTMLElement
}

/**
 * Builds the GameDefinition for the boot-and-flow demo (spec §8).
 * Configures the seams and boot options according to the requested ?fail= mode.
 */
export function demoGame(fail?: FailMode, seams?: DemoGameSeams): GameDefinition<unknown> {
  const root =
    seams?.root ??
    (typeof document !== 'undefined'
      ? (document.getElementById('game') ?? document.createElement('div'))
      : ({} as HTMLElement))

  // Fail mode: init -> invalid testHostOrigins causes Ruken.init to fail
  const hosting = {
    gameId: 'demo-runtime-boot-and-flow',
    wants: ['saves'] as const,
    pauseBehavior: 'pause' as const,
    ...(fail === 'init' ? { testHostOrigins: ['not a valid url'] } : {}),
  }

  // Fail mode: saves -> key with spaces rejected by SAVE_KEY_RE (/^[A-Za-z0-9._:-]{1,128}$/)
  const settings =
    fail === 'saves'
      ? {
          key: 'invalid key with spaces',
          version: 1,
          schema: z.object({}),
          defaults: {},
        }
      : {
          key: 'demo_settings',
          version: 1,
          schema: z.object({
            sound: z.boolean().catch(true),
          }),
          defaults: { sound: true },
        }

  // Fail mode: content -> hash mismatch
  const hash = fail === 'content' ? '0000000000000000' : '0380789e85f9ade4'
  const content = {
    data: demoContentData,
    hash,
  }

  // Fail mode: renderer -> nullRenderer with fail: true
  const renderer = fail === 'renderer' ? nullRenderer([], { fail: true }) : nullRenderer()

  // Fail mode: download -> 404, stall -> hang
  let fetchFn = seams?.fetch ?? (typeof globalThis !== 'undefined' ? globalThis.fetch : undefined)
  if (fail === 'download') {
    const mock = fakeFetch(
      { '/assets/title.txt': { status: 404 } },
      fetchFn ? { fallback: fetchFn } : undefined,
    )
    fetchFn = mock.fetch
  } else if (fail === 'stall') {
    const mock = fakeFetch(
      { '/assets/title.txt': { hang: true } },
      fetchFn ? { fallback: fetchFn } : undefined,
    )
    fetchFn = mock.fetch
  }

  const effectiveSeams: RuntimeSeams = {
    ...seams,
    ...(fetchFn ? { fetch: fetchFn } : {}),
  }

  return {
    root,
    hosting,
    content,
    screens: [titleScreen, playScreen, pausedScreen],
    renderer,
    settings,
    seams: effectiveSeams,
  }
}

